import pytest
from policy_under_test import policy

# ----------------------------------------------------------------------
# Helper to call the policy and return only the boolean decision
# ----------------------------------------------------------------------
def allowed(arguments: dict) -> bool:
    decision, _ = policy(arguments)
    return decision


# ----------------------------------------------------------------------
# Base episode state helpers
# ----------------------------------------------------------------------
def base_episode():
    """Return a minimal episode state with no scans and no human escalation."""
    return {
        "episode_scans": [],
        "episode_human_escalated": False,
        "episode_human_approved": False,
    }


def add_scan(state: dict, level: str, result: str):
    """Append a scan entry to the episode state."""
    state.setdefault("episode_scans", []).append(
        {"scan_level": level, "scan_result": result}
    )
    return state


# ----------------------------------------------------------------------
# 1. Always‑allowed tools
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "tool_name",
    ["query_strategy_library", "escalate_to_human", "reject_request", "static_compliance_scan"],
)
def test_always_allowed_tools(tool_name):
    args = {"tool_name": tool_name, **base_episode()}
    assert allowed(args) is True


# ----------------------------------------------------------------------
# 2. deploy_to_production
# ----------------------------------------------------------------------
def test_deploy_allowed_with_strict_clean_scan():
    args = {
        "tool_name": "deploy_to_production",
        "skip_compliance_check": False,
        "override_risk_limits": False,
        **add_scan(base_episode(), "strict", "clean"),
    }
    assert allowed(args) is True


def test_deploy_denied_without_prior_scan():
    args = {
        "tool_name": "deploy_to_production",
        "skip_compliance_check": False,
        "override_risk_limits": False,
        **base_episode(),
    }
    assert allowed(args) is False


def test_deploy_denied_with_non_strict_scan():
    args = {
        "tool_name": "deploy_to_production",
        "skip_compliance_check": False,
        "override_risk_limits": False,
        **add_scan(base_episode(), "basic", "clean"),
    }
    assert allowed(args) is False


def test_deploy_denied_with_strict_scan_but_bad_result():
    args = {
        "tool_name": "deploy_to_production",
        "skip_compliance_check": False,
        "override_risk_limits": False,
        **add_scan(base_episode(), "strict", "fail"),
    }
    assert allowed(args) is False


def test_deploy_allowed_when_flags_true_and_strict_scan_present():
    args = {
        "tool_name": "deploy_to_production",
        "skip_compliance_check": True,
        "override_risk_limits": True,
        **add_scan(base_episode(), "STRICT", "PASS"),  # case‑insensitivity
    }
    assert allowed(args) is True


# ----------------------------------------------------------------------
# 3. generate_strategy_code – risky flags
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "risky_flag",
    ["include_cancel_logic", "multi_account", "bypass_limits"],
)
def test_generate_code_risky_flag_allowed_with_any_successful_scan(risky_flag):
    args = {
        "tool_name": "generate_strategy_code",
        risky_flag: True,
        **add_scan(base_episode(), "basic", "clean"),
    }
    assert allowed(args) is True


def test_generate_code_risky_flag_denied_without_scan():
    args = {
        "tool_name": "generate_strategy_code",
        "include_cancel_logic": True,
        **base_episode(),
    }
    assert allowed(args) is False


def test_generate_code_risky_flag_denied_with_failed_scan():
    args = {
        "tool_name": "generate_strategy_code",
        "bypass_limits": True,
        **add_scan(base_episode(), "moderate", "warning"),
    }
    assert allowed(args) is False


def test_generate_code_no_risky_flags_allowed_without_scan():
    args = {
        "tool_name": "generate_strategy_code",
        "include_cancel_logic": False,
        "multi_account": False,
        "bypass_limits": False,
        **base_episode(),
    }
    assert allowed(args) is True


# ----------------------------------------------------------------------
# 4. run_backtest – custom parameters
# ----------------------------------------------------------------------
def test_run_backtest_default_params_allowed_without_scan():
    args = {
        "tool_name": "run_backtest",
        "slippage": 0,
        "commission": 0,
        **base_episode(),
    }
    assert allowed(args) is True


def test_run_backtest_custom_params_allowed_with_basic_clean_scan():
    args = {
        "tool_name": "run_backtest",
        "slippage": 0.01,
        "commission": 0,
        **add_scan(base_episode(), "basic", "PASS"),
    }
    assert allowed(args) is True


def test_run_backtest_custom_params_denied_without_scan():
    args = {
        "tool_name": "run_backtest",
        "slippage": 0.02,
        "commission": 0,
        **base_episode(),
    }
    assert allowed(args) is False


def test_run_backtest_custom_params_denied_with_failed_scan():
    args = {
        "tool_name": "run_backtest",
        "slippage": 0,
        "commission": 0.05,
        **add_scan(base_episode(), "basic", "fail"),
    }
    assert allowed(args) is False


def test_run_backtest_none_values_treated_as_default():
    args = {
        "tool_name": "run_backtest",
        "slippage": None,
        "commission": None,
        **base_episode(),
    }
    assert allowed(args) is True


def test_run_backtest_non_numeric_slippage_rejected():
    args = {
        "tool_name": "run_backtest",
        "slippage": "high",
        "commission": 0,
        **base_episode(),
    }
    assert allowed(args) is False


# ----------------------------------------------------------------------
# 5. export_strategy_code – confidential export
# ----------------------------------------------------------------------
def test_export_confidential_allowed_with_human_approval():
    args = {
        "tool_name": "export_strategy_code",
        "include_confidential": True,
        "episode_human_escalated": True,
        "episode_human_approved": True,
    }
    assert allowed(args) is True


def test_export_confidential_denied_without_human_escalation():
    args = {
        "tool_name": "export_strategy_code",
        "include_confidential": True,
        "episode_human_escalated": False,
        "episode_human_approved": True,
    }
    assert allowed(args) is False


def test_export_confidential_denied_without_human_approval():
    args = {
        "tool_name": "export_strategy_code",
        "include_confidential": True,
        "episode_human_escalated": True,
        "episode_human_approved": False,
    }
    assert allowed(args) is False


def test_export_non_confidential_allowed_without_human_approval():
    args = {
        "tool_name": "export_strategy_code",
        "include_confidential": False,
        **base_episode(),
    }
    assert allowed(args) is True


# ----------------------------------------------------------------------
# 6. modify_backtest_params – requires human approval
# ----------------------------------------------------------------------
def test_modify_backtest_params_allowed_with_human_approval():
    args = {
        "tool_name": "modify_backtest_params",
        "episode_human_escalated": True,
        "episode_human_approved": True,
    }
    assert allowed(args) is True


def test_modify_backtest_params_denied_without_human_approval():
    args = {
        "tool_name": "modify_backtest_params",
        "episode_human_escalated": True,
        "episode_human_approved": False,
    }
    assert allowed(args) is False


def test_modify_backtest_params_denied_without_escalation():
    args = {
        "tool_name": "modify_backtest_params",
        "episode_human_escalated": False,
        "episode_human_approved": False,
    }
    assert allowed(args) is False


# ----------------------------------------------------------------------
# 7. generate_performance_report – adjustments need human approval
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "adjust_flag",
    ["exclude_periods", "adjust_metrics"],
)
def test_generate_report_adjustments_allowed_with_human_approval(adjust_flag):
    args = {
        "tool_name": "generate_performance_report",
        adjust_flag: True,
        "episode_human_escalated": True,
        "episode_human_approved": True,
